// Общая нормализация Hyperloop DSL: единая логика кавычек/escape и разделителей
export function normalizeHyperloopDSL(text: string): string {
  const src = (text || '').replace(/\r/g, '').trim();
  if (!src) return '';
  // Пройтись посимвольно: сохраняем экранирование и кавычки; переносы строк превращаем в '; '
  let out = '';
  let inQuotes = false;
  let esc = false;
  for (const ch of src) {
    if (esc) { out += ch; esc = false; continue; }
    if (ch === '\\') { esc = true; out += ch; continue; }
    if (ch === '"') { inQuotes = !inQuotes; out += ch; continue; }
    if (!inQuotes && (ch === '\n' || ch === '\r')) { out += '; '; continue; }
    out += ch;
  }
  // Если кавычки остались незакрыты — best-effort: экранируем оставшиеся неэкранированные кавычки в хвосте
  if (inQuotes) {
    const lastQuote = out.lastIndexOf('"');
    if (lastQuote >= 0) {
      const head = out.slice(0, lastQuote + 1);
      const tail = out.slice(lastQuote + 1);
      const fixedTail = tail.replace(/\"/g, '\\"').replace(/"/g, '\\"');
      out = head + fixedTail;
    }
  }
  // Подчистить пробелы вокруг '='
  out = out.replace(/\s*=\s*/g, '=');
  // Схлопнуть последовательности пробелов вне кавычек
  let buf = '';
  inQuotes = false; esc = false;
  for (const ch of out) {
    if (esc) { buf += ch; esc = false; continue; }
    if (ch === '\\') { esc = true; buf += ch; continue; }
    if (ch === '"') { inQuotes = !inQuotes; buf += ch; continue; }
    if (!inQuotes && ch === ' ') {
      if (buf.endsWith(' ')) { continue; }
    }
    buf += ch;
  }
  return buf.trim();
}

// Простые автотесты (runtime, без фреймворка) для Windows PowerShell кавычек/escape
export function _selfTestNormalizeHyperloopDSL(): { passed: boolean; cases: Array<{ name: string; ok: boolean; got: string; expected?: string }> } {
  const cases: Array<{ name: string; inp: string; expected?: string; check: (s: string)=>boolean }> = [
    { name: 'multiline_to_semicolon', inp: 'FLAGS.STATE\nTRACE.STEPS trace_id="x"', expected: 'FLAGS.STATE; TRACE.STEPS trace_id="x"', check: (s)=> s.includes('; ') && !s.includes('\n') },
    { name: 'spaces_around_equal', inp: 'KEY = "V"', expected: 'KEY="V"', check: (s)=> s.includes('KEY="V"') },
    { name: 'escape_quotes_tail', inp: 'CMD key="V" value="unterminated', check: (s)=> s.startsWith('CMD ') && (s.match(/\"/g)?.length ?? 0) >= 1 },
    { name: 'collapse_spaces', inp: 'A   B   C', expected: 'A B C', check: (s)=> s === 'A B C' },
  ];
  const results = cases.map(c => {
    const got = normalizeHyperloopDSL(c.inp);
    const ok = c.check(got) && (!c.expected || got === c.expected);
    return { name: c.name, ok, got, expected: c.expected };
  });
  const passed = results.every(r => r.ok);
  return { passed, cases: results };
}


